      "status": "suspected",
      "proposed_checks": [
        "test -f /app/submissions/model.md && echo 'exists' || echo 'missing'"
      ]
    },
    {
      "req_ids": [],
      "problem_type": "feasibility",
      "detail": "Supply is 1000 + 1500 = 2500 units, while total demand is 80 + 90 + 80 = 250 units (if in boxes) or 2500 units (if in pieces). If demand is in boxes and should be converted to pieces (250 * 10 = 2500), supply exactly matches demand. If demand is already in pieces, supply greatly exceeds demand. The feasibility depends on correct unit interpretation. The current code treats demand as 250 units total, leaving 2250 units of unused supply, which may or may not be intended.",
      "evidence_level": "llm_judgment",
      "status": "suspected",
      "proposed_checks": [
        "python3 -c \"import csv; s=sum(float(r['supply']) for r in csv.DictReader(open('/home/hewj13/wm/ora/work/controlled_eval/tiny_transport_b_m2_blind/app/data/supply.csv'))); d=sum(float(r['demand']) for r in csv.DictReader(open('/home/hewj13/wm/ora/work/controlled_eval/tiny_transport_b_m2_blind/app/data/demand.csv'))); print(f'supply={s}, demand={d}, ratio={s/d:.2f}')\""
      ]
    }
  ]
}

